from urllib.parse import urlparse

def is_valid_subdomain(target: str, domain: str) -> bool:
    parsed_target = urlparse(target)
    if parsed_target.hostname:
        target_domain_parts = parsed_target.hostname.split('.')
        domain_parts = domain.split('.')
        return target_domain_parts[-len(domain_parts):] == domain_parts and (
            len(target_domain_parts) == len(domain_parts) or target_domain_parts[-len(domain_parts)-1] == ''
        )
    return False

# Test cases
print(is_valid_subdomain('https://music.example.com', 'example.com'))  # True

