from urllib.parse import urlparse

def is_subdomain(target: str, domain: str) -> bool:
    parsed_target = urlparse(target)
    if parsed_target.hostname:
        target_domain_parts = parsed_target.hostname.split('.')
        domain_parts = domain.split('.')
        return target_domain_parts[-len(domain_parts):] == domain_parts and (
            len(target_domain_parts) > len(domain_parts)
        )

# Test cases
print(is_subdomain('https://music.example.com', 'example.com'))  # True
print(is_subdomain('https://example.com', 'example.com'))        # False
